  describe('API Gateway v2', () => {
    it('Should return the client IP from http.sourceIp', () => {
      const ip = '198.51.100.23'
      const c = new Context(new Request('http://localhost/'), {
        env: {
          requestContext: {
            http: {
              method: 'GET',
              path: '/',
              protocol: 'HTTP/1.1',
              sourceIp: ip,
              userAgent: 'test',
