          upgrade(_req: Request, options: { data: BunWebSocketData }) {
            data = options.data
            return true
          },
        },
      }),
      () => Promise.resolve()
    )

    const ws = createWSContext({ data, readyState: 1 } as BunServerWebSocket<BunWebSocketData>)
    expect(ws.protocol).toBe('')
  })
