    )
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/bravo.text/index.html', 'About Page')
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/bravo.text/index.html', 'Bravo Page')
    // binary files
    expect(fsMock.writeFile).toHaveBeenCalledWith(
      'static/bravo/index.tar.gz',
      new Uint8Array(gzFileArrayBuffer)
    )
    expect(fsMock.writeFile).toHaveBeenCalledWith(
      'static/bravo/dot.png',
      new Uint8Array(pngFileArrayBuffer)
    )
  })

  it('should correctly create directories if they do not exist', async () => {
    await saveContentToFile(
      Promise.resolve({
        routePath: '/new-dir/index.html',
        content: 'New Page',
        mimeType: 'text/html',
      }),
      fsMock,
      './static'
    )
    expect(fsMock.mkdir).toHaveBeenCalledWith('static/new-dir', { recursive: true })
  })

  it('should handle file writing or directory creation errors', async () => {
    const fsMock: FileSystemModule = {
      writeFile: vi.fn(() => Promise.resolve()),
      mkdir: vi.fn(() => Promise.reject(new Error('File write error'))),
    }

    await expect(
      saveContentToFile(
        Promise.resolve({
          routePath: '/error-dir/index.html',
          content: 'New Page',
          mimeType: 'text/html',
        }),
        fsMock,
        './static'
      )
    ).rejects.toThrow('File write error')
  })
  it('check extensions', async () => {
    for (const data of fileData) {
      await saveContentToFile(Promise.resolve(data), fsMock, './static-check-extensions')
    }
    expect(fsMock.mkdir).toHaveBeenCalledWith('static-check-extensions', { recursive: true })
  })

  it('should correctly create .yaml files for YAML content', async () => {
    const yamlContent = 'title: YAML Example\nvalue: This is a YAML file.'
    const mimeType = 'application/yaml'
    const routePath = '/example'

    const yamlData = {
      routePath: routePath,
      content: yamlContent,
      mimeType: mimeType,
    }

    const fsMock: FileSystemModule = {
      writeFile: vi.fn(() => Promise.resolve()),
      mkdir: vi.fn(() => Promise.resolve()),
    }

    await saveContentToFile(Promise.resolve(yamlData), fsMock, './static')

    expect(fsMock.writeFile).toHaveBeenCalledWith('static/example.yaml', yamlContent)
  })

  it('should correctly create .yml files for YAML content', async () => {
    const yamlContent = 'title: YAML Example\nvalue: This is a YAML file.'
    const yamlMimeType = 'application/yaml'
    const yamlRoutePath = '/yaml'

    const yamlData = {
      routePath: yamlRoutePath,
      content: yamlContent,
      mimeType: yamlMimeType,
    }

    const yamlMimeType2 = 'x-yaml'
    const yamlRoutePath2 = '/yaml2'
    const yamlData2 = {
      routePath: yamlRoutePath2,
      content: yamlContent,
      mimeType: yamlMimeType2,
    }

    const htmlMimeType = 'text/html'
    const htmlRoutePath = '/html'

    const htmlData = {
      routePath: htmlRoutePath,
      content: yamlContent,
      mimeType: htmlMimeType,
    }

    const atomData = {
      routePath: '/atom',
      content: yamlContent,
      mimeType: 'application/atom+xml',
    }

    const rssData = {
      routePath: '/rss',
      content: yamlContent,
      mimeType: 'application/rss+xml',
    }

    const fsMock: FileSystemModule = {
      writeFile: vi.fn(() => Promise.resolve()),
      mkdir: vi.fn(() => Promise.resolve()),
    }

    const extensionMap = {
      'application/yaml': 'yml',
      'x-yaml': 'xyml',
    }
    await saveContentToFile(Promise.resolve(yamlData), fsMock, './static', extensionMap)
    await saveContentToFile(Promise.resolve(yamlData2), fsMock, './static', extensionMap)
    await saveContentToFile(Promise.resolve(htmlData), fsMock, './static', extensionMap)
    await saveContentToFile(Promise.resolve(htmlData), fsMock, './static', {
      ...defaultExtensionMap,
      ...extensionMap,
    })
    await saveContentToFile(Promise.resolve(atomData), fsMock, './static')
    await saveContentToFile(Promise.resolve(rssData), fsMock, './static')

    expect(fsMock.writeFile).toHaveBeenCalledWith('static/yaml.yml', yamlContent)
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/yaml2.xyml', yamlContent)
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/html.htm', yamlContent) // extensionMap
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/html.html', yamlContent) // default + extensionMap
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/atom.xml', yamlContent)
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/rss.xml', yamlContent)
  })

  it('should determine the extension case-insensitively', async () => {
    const htmlData = { routePath: '/html', content: 'Hello', mimeType: 'TEXT/HTML' }
    const jsonData = { routePath: '/json', content: '{}', mimeType: 'APPLICATION/JSON' }
    const xmlData = { routePath: '/xml', content: '<a/>', mimeType: 'APPLICATION/XML' }
    const fooData = { routePath: '/foo', content: 'foo', mimeType: 'TEXT/X-FOO' }
    const barData = { routePath: '/bar', content: 'bar', mimeType: 'TEXT/X-BAR' }

    await saveContentToFile(Promise.resolve(htmlData), fsMock, './static')
    await saveContentToFile(Promise.resolve(jsonData), fsMock, './static')
    await saveContentToFile(Promise.resolve(xmlData), fsMock, './static')
    await saveContentToFile(Promise.resolve(fooData), fsMock, './static', { 'text/x-foo': 'foo' })
    await saveContentToFile(Promise.resolve(barData), fsMock, './static', { 'TEXT/X-BAR': 'bar' })

    expect(fsMock.writeFile).toHaveBeenCalledWith('static/html.html', 'Hello')
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/json.json', '{}')
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/xml.xml', '<a/>')
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/foo.foo', 'foo')
    expect(fsMock.writeFile).toHaveBeenCalledWith('static/bar.bar', 'bar')
  })

  it('should reject writing files outside outDir via path traversal', async () => {
    await expect(
      saveContentToFile(
        Promise.resolve({
          routePath: '/../pwned',
          content: 'owned',
          mimeType: 'text/html',
        }),
        fsMock,
        './static'
      )
    ).rejects.toThrow('Path traversal detected')

    expect(fsMock.mkdir).not.toHaveBeenCalled()
    expect(fsMock.writeFile).not.toHaveBeenCalled()
  })

  it('should reject paths that only partially match outDir name', async () => {
    await expect(
      saveContentToFile(
        Promise.resolve({
          routePath: '/../static-evil/pwned',
          content: 'owned',
          mimeType: 'text/html',
        }),
        fsMock,
        './static'
      )
    ).rejects.toThrow('Path traversal detected')

    expect(fsMock.mkdir).not.toHaveBeenCalled()
    expect(fsMock.writeFile).not.toHaveBeenCalled()
  })
})

