c=d.currentScript.previousSibling
d=d.getElementById('E:${errorBoundaryCounter}')
if(!d)return
d.parentElement.insertBefore(c.content,d.nextSibling)
})(document)
</script>`,
        `<template data-hono-target="E:${errorBoundaryCounter}"><div>Out Of Service</div></template><script nonce="test-nonce">
((d,c,n) => {
c=d.currentScript.previousSibling
d=d.getElementById('E:${errorBoundaryCounter}')
if(!d)return
do{n=d.nextSibling;n.remove()}while(n.nodeType!=8||n.nodeValue!='E:${errorBoundaryCounter}')
d.replaceWith(c.content)
})(document)
</script>`,
      ])

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>Out Of Service</div>'
      )
    })

    it('error', async () => {
      const html = (
        <ErrorBoundary fallback={<Fallback />}>
          <Component error={true} />
        </ErrorBoundary>
      )

      expect((await resolveCallback(await html.toString())).toString()).toEqual(
        '<div>Out Of Service</div>'
      )
    })
  })

  describe('streaming : contains multiple suspense', async () => {
    const handlers: Record<number, { resolve: (value: unknown) => void; reject: () => void }> = {}
    const Component = async ({ id }: { id: number }) => {
      await new Promise((resolve, reject) => (handlers[id] = { resolve, reject }))
      return <div>{id}</div>
    }

    it('no error', async () => {
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={2} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={3} />
          </Suspense>
        </ErrorBoundary>
      )

      Object.values(handlers).forEach(({ resolve }) => resolve(undefined))

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>1</div><div>2</div><div>3</div>'
      )
    })

    it('error', async () => {
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={2} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={3} />
          </Suspense>
        </ErrorBoundary>
      )

      handlers[1].resolve(undefined)
      handlers[2].resolve(undefined)
      handlers[3].reject()

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>Out Of Service</div>'
      )
    })

    it('renders fallback and reports error once when multiple children reject', async () => {
      let fallbackRenderCount = 0
      let onErrorCount = 0
      const stream = renderToReadableStream(
        <ErrorBoundary
          fallbackRender={() => {
            fallbackRenderCount++
            return <Fallback />
          }}
          onError={() => {
            onErrorCount++
          }}
        >
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={2} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={3} />
          </Suspense>
        </ErrorBoundary>
      )

      handlers[1].reject()
      handlers[2].reject()
      handlers[3].resolve(undefined)

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>Out Of Service</div>'
      )
      expect(fallbackRenderCount).toBe(1)
      expect(onErrorCount).toBe(1)
    })

    it('preserves callbacks from a thenable fallback', async () => {
      const fallback = Promise.resolve(
        raw('<span>Recovering</span>', [
          ({ phase }) =>
            phase === HtmlEscapedCallbackPhase.Stream
              ? Promise.resolve('<span>Recovered</span>')
              : undefined,
        ])
      )
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={fallback}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
        </ErrorBoundary>
      )

      handlers[1].reject()

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<span>Recovering</span><span>Recovered</span>'
      )
    })

    it('waits for an in-flight async fallback when multiple children reject', async () => {
      let resolveFallback!: (value: HtmlEscapedString | PromiseLike<HtmlEscapedString>) => void
      const fallback = new Promise<HtmlEscapedString>((resolve) => {
        resolveFallback = resolve
      })

      const stream = renderToReadableStream(
        <ErrorBoundary fallback={fallback}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={2} />
          </Suspense>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={3} />
          </Suspense>
        </ErrorBoundary>
      )

      handlers[1].reject()
      handlers[2].reject()
      handlers[3].resolve(undefined)
      await Promise.resolve()
      resolveFallback(<Fallback />)

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>Out Of Service</div>'
      )
    })
  })

  describe('streaming : nested', async () => {
    const handlers: Record<number, { resolve: (value: unknown) => void; reject: () => void }> = {}
    const Component = async ({ id }: { id: number }) => {
      await new Promise((resolve, reject) => (handlers[id] = { resolve, reject }))
      return <div>{id}</div>
    }

    it('no error', async () => {
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <ErrorBoundary fallback={<Fallback />}>
            <Suspense fallback={<p>Loading...</p>}>
              <Component id={2} />
            </Suspense>
          </ErrorBoundary>
        </ErrorBoundary>
      )

      Object.values(handlers).forEach(({ resolve }) => resolve(undefined))

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>1</div><div>2</div>'
      )
    })

    it('error in parent', async () => {
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <ErrorBoundary fallback={<Fallback />}>
            <Suspense fallback={<p>Loading...</p>}>
              <Component id={2} />
            </Suspense>
          </ErrorBoundary>
        </ErrorBoundary>
      )

      handlers[2].resolve(undefined)
      handlers[1].reject()

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>Out Of Service</div>'
      )
    })

    it('error in child', async () => {
      const stream = renderToReadableStream(
        <ErrorBoundary fallback={<Fallback />}>
          <Suspense fallback={<p>Loading...</p>}>
            <Component id={1} />
          </Suspense>
          <ErrorBoundary fallback={<Fallback />}>
            <Suspense fallback={<p>Loading...</p>}>
              <Component id={2} />
            </Suspense>
          </ErrorBoundary>
        </ErrorBoundary>
      )

      handlers[1].resolve(undefined)
      handlers[2].reject()

      const chunks = []
      const textDecoder = new TextDecoder()
      for await (const chunk of stream as any) {
        chunks.push(textDecoder.decode(chunk))
      }

      expect(replacementResult(`<html><body>${chunks.join('')}</body></html>`)).toEqual(
        '<div>1</div><div>Out Of Service</div>'
      )
    })
  })

  describe('onError', async () => {
    const Component = ({ error }: { error?: boolean }) => {
      if (error) {
        throw new Error('Error')
      }
      return <div>Hello</div>
    }

    it('no error', async () => {
      const errors: Error[] = []
      const html = (
        <ErrorBoundary fallback={<Fallback />} onError={(err) => errors.push(err)}>
          <Component />
        </ErrorBoundary>
      )

      expect((await resolveCallback(await html.toString())).toString()).toEqual('<div>Hello</div>')

      errorBoundaryCounter--
      suspenseCounter--

      expect(errors).toEqual([])
    })

    it('error', async () => {
      const errors: Error[] = []
      const html = (
        <ErrorBoundary fallback={<Fallback />} onError={(err) => errors.push(err)}>
          <Component error={true} />
        </ErrorBoundary>
      )

      expect((await resolveCallback(await html.toString())).toString()).toEqual(
        '<div>Out Of Service</div>'
      )

      suspenseCounter--

      expect(errors[0]).toEqual(new Error('Error'))
    })
  })

  describe('fallbackRender', async () => {
    const fallbackRenderer = (error: Error) => <div data-error>{error.message}</div>
    const Component = ({ error }: { error?: boolean }) => {
      if (error) {
        throw new Error('Error')
      }
      return <div>Hello</div>
    }

    it('no error', async () => {
      const errors: Error[] = []
      const html = (
        <ErrorBoundary fallbackRender={fallbackRenderer}>
          <Component />
        </ErrorBoundary>
      )

      expect((await resolveCallback(await html.toString())).toString()).toEqual('<div>Hello</div>')

      errorBoundaryCounter--
      suspenseCounter--

      expect(errors).toEqual([])
    })

    it('error', async () => {
      const html = (
        <ErrorBoundary fallbackRender={fallbackRenderer}>
          <Component error={true} />
        </ErrorBoundary>
      )

      expect((await resolveCallback(await html.toString())).toString()).toEqual(
        '<div data-error="true">Error</div>'
      )

      suspenseCounter--
    })
  })

  describe('escaping', () => {
    const Broken = () => {
      throw new Error('boom')
    }

    it('escapes strings when an asynchronous sibling is present', async () => {
      const Async = async () => <span>done</span>
      const node = (
        <ErrorBoundary fallback='error'>
          {unsafeHtml}
          <Async />
        </ErrorBoundary>
      )

      expect(await stringify(node)).toBe(`${escapedUnsafeHtml}<span>done</span>`)
      const streamed = await drainStream(renderToReadableStream(node))
      expect(streamed).toContain(escapedUnsafeHtml)
      expect(streamed).not.toContain(unsafeHtml)
    })

    it('escapes untrusted object fallbacks', async () => {
      const object = { toString: () => unsafeHtml }
      const asyncObject = { toString: async () => unsafeHtml }
      const rawObject = { toString: () => raw(unsafeHtml) }

      for (const fallback of [object, asyncObject, rawObject]) {
        expect(
          await stringify(
            <ErrorBoundary fallback={fallback as never}>
              <Broken />
            </ErrorBoundary>
          )
        ).toBe(escapedUnsafeHtml)
      }
    })

    it('preserves an explicitly trusted fallback', async () => {
      expect(
        await stringify(
          <ErrorBoundary fallback={raw('<strong>trusted</strong>')}>
            <Broken />
          </ErrorBoundary>
        )
      ).toBe('<strong>trusted</strong>')
    })

    it('does not interpret replacement patterns in content', async () => {
      const content = "literal $& $` $'"
      const Async = async () => <span>done</span>

      expect(
        await stringify(
          <ErrorBoundary fallback='error'>
            {content}
            <Async />
          </ErrorBoundary>
        )
      ).toBe('literal $&amp; $` $&#39;<span>done</span>')
    })

    it('escapes untrusted object children', async () => {
      const object = { toString: () => unsafeHtml }
      const asyncObject = { toString: async () => unsafeHtml }
      const rawObject = { toString: () => raw(unsafeHtml) }

      for (const child of [object, asyncObject, rawObject]) {
        const node = <ErrorBoundary fallback='error'>{child as never}</ErrorBoundary>
        expect(await stringify(node)).toBe(escapedUnsafeHtml)
        const streamed = await drainStream(renderToReadableStream(node))
        expect(streamed).toContain(escapedUnsafeHtml)
        expect(streamed).not.toContain(unsafeHtml)
      }
    })

    it('preserves explicitly trusted children', async () => {
      expect(
        await stringify(
          <ErrorBoundary fallback='error'>{raw('<strong>trusted</strong>')}</ErrorBoundary>
        )
      ).toBe('<strong>trusted</strong>')
    })

    it('keeps benign object stringification visible', async () => {
      expect(await stringify(<ErrorBoundary fallback='error'>{{} as never}</ErrorBoundary>)).toBe(
        '[object Object]'
      )
    })

    it('escapes nested fallback arrays', async () => {
      expect(
        await stringify(
          <ErrorBoundary fallback={[[unsafeHtml]]}>
            <Broken />
          </ErrorBoundary>
        )
      ).toBe(escapedUnsafeHtml)
    })

    it('keeps the existing falsy fallbackRender behavior', async () => {
      expect(
        await stringify(
          <ErrorBoundary fallbackRender={() => 0}>
            <Broken />
          </ErrorBoundary>
        )
      ).toBe('')
    })

    it('keeps a direct Promise child unchanged', async () => {
      expect(
        await stringify(
          <ErrorBoundary fallback='error'>{Promise.resolve('resolved')}</ErrorBoundary>
        )
      ).toBe('[object Promise]')
    })
  })
})

