      return jsx(
        Fragment,
        {},
        jsx(ThemeContext.Provider, { value: 'inner' }, jsx(Inner, {})),
        jsx(OuterSibling, {})
      )
    }

    const html = await drainStream(
      renderToReadableStream(
        jsx(
          ThemeContext.Provider,
          { value: 'outer' },
