        throw deferred
      }
      return jsx(ThemeContext.Provider, { value: resolved }, jsx(Inner, {}))
    }

    const html = await drainStream(
      renderToReadableStream(
        jsx(ErrorBoundary, { fallback: jsx('p', {}, 'Failed') }, jsx(Content, {}))
