async function dispatch(i: number): Promise<Context> {
  if (i <= index) {
    throw new Error('next() called multiple times')
  }
  index = i

  let res
  let isError = false
  let handler

  if (middleware[i]) {
    handler = middleware[i][0][0]
    context.req.routeIndex = i
  } else {
    handler = (i === middleware.length && next) || undefined
  }

  if (handler) {
    try {
      res = await handler(context, () => dispatch(i + 1))
    } catch (err) {
      if (err instanceof Error && onError) {
        context.error = err
        res = await onError(err, context)
        isError = true
      } else {
        throw err
      }
    }
  } else {
    if (context.finalized === false && onNotFound) {
      res = await onNotFound(context)
    }
  }

  if (res && (context.finalized === false || isError)) {
    context.res = res
  }
  return context
}

const makeResponseHeaderImmutable = (res: Response) => {
  Object.defineProperty(res, 'headers', {
    value: new Proxy(res.headers, {
      set(target, prop, value) {
        if (prop === 'set') {
          throw new TypeError('Cannot modify headers: Headers are immutable')
        }
        return Reflect.set(target, prop, value)
      },
      get(target, prop, receiver) {
        if (prop === 'set') {
          return function () {
            throw new TypeError('Cannot modify headers: Headers are immutable')
          }
        }
        const value = Reflect.get(target, prop)
        if (typeof value === 'function') {
          return Object.defineProperties(
            function (...args: unknown[]) {
              // @ts-expect-error: `this` context is intentionally dynamic for proxy method binding
              return Reflect.apply(value, this === receiver ? target : this, args)
            },
            {
              name: { value: value.name },
              length: { value: value.length },
            }
          )
        }
        return value
      },
    }),
    writable: false,
  })
  return res
}

