export class HTTPException extends Error {
  readonly res?: Response
  readonly status: ContentfulStatusCode

  /**
   * Creates an instance of `HTTPException`.
   * @param status - HTTP status code for the exception. Defaults to 500.
   * @param options - Additional options for the exception.
   */
  constructor(status: ContentfulStatusCode = 500, options?: HTTPExceptionOptions) {
    super(options?.message, { cause: options?.cause })
    this.res = options?.res
    this.status = status
  }

  /**
   * Returns the response object associated with the exception.
   * If a response object is not provided, a new response is created with the error message and status code.
   * @returns The response object.
   */
  getResponse(): Response {
    if (this.res) {
      const newResponse = new Response(this.res.body, {
        status: this.status,
        headers: this.res.headers,
      })
      return newResponse
    }
    return new Response(this.message, {
      status: this.status,
    })
  }
}

constructor(status: ContentfulStatusCode = 500, options?: HTTPExceptionOptions) {
  super(options?.message, { cause: options?.cause })
  this.res = options?.res
  this.status = status
}

getResponse(): Response {
  if (this.res) {
    const newResponse = new Response(this.res.body, {
      status: this.status,
      headers: this.res.headers,
    })
    return newResponse
  }
  return new Response(this.message, {
    status: this.status,
  })
}

export const markRenderedJSX = (value: HtmlEscapedString): HtmlEscapedString => {
  ;(value as unknown as Record<symbol, boolean>)[RENDERED_JSX] = true
  return value
}

const objectToAttributeString = (v: object): string | Promise<string> => {
  const s = v.toString() as string | Promise<string>
  return s instanceof Promise ? s.then(String) : String(s)
}

const childrenToStringToBuffer = (children: Child[], buffer: StringBufferWithCallbacks): void => {
  for (let i = 0, len = children.length; i < len; i++) {
    const child = children[i]
    if (typeof child === 'string') {
      escapeToBuffer(child, buffer)
    } else if (typeof child === 'boolean' || child === null || child === undefined) {
      continue
    } else if (child instanceof JSXNode) {
      child.toStringToBuffer(buffer)
    } else if (typeof child === 'number') {
      ;(buffer[0] as string) += child
    } else if ((child as unknown as HtmlEscaped).isEscaped) {
      ;(buffer[0] as string) += child
      const callbacks = (child as unknown as HtmlEscapedString).callbacks
      if (callbacks) {
        buffer.callbacks ||= []
        buffer.callbacks.push(...callbacks)
      }
    } else if (child instanceof Promise) {
      buffer.unshift('', child)
    } else {
      // `child` type is `Child[]`, so stringify recursively
      childrenToStringToBuffer(child, buffer)
    }
  }
}

export class JSXNode implements HtmlEscaped {
  tag: string | Function
  props: Props
  key?: string
  children: Child[]
  isEscaped: true = true as const
  constructor(tag: string | Function, props: Props, children: Child[]) {
    if (typeof tag !== 'function' && !isValidTagName(tag)) {
      throw new Error(`Invalid JSX tag name: ${tag}`)
    }
    this.tag = tag
    this.props = props
    this.children = children
  }

  get type(): string | Function {
    return this.tag as string
  }

  // Added for compatibility with libraries that rely on React's internal structure
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  get ref(): any {
    return this.props.ref || null
  }

  toString(): string | Promise<string> {
    const render = () => {
      const buffer: StringBufferWithCallbacks = [''] as StringBufferWithCallbacks
      this.toStringToBuffer(buffer)
      return buffer.length === 1
        ? 'callbacks' in buffer
          ? resolveCallbackSync(raw(buffer[0], buffer.callbacks)).toString()
          : buffer[0]
        : stringBufferToString(buffer, buffer.callbacks).then(markRenderedJSX)
    }
    return runWithRenderContext(render)
  }

  toStringToBuffer(buffer: StringBufferWithCallbacks): void {
    const tag = this.tag as string
    const props = this.props
    let { children } = this

    buffer[0] += `<${tag}`

    const normalizeKey: (key: string) => string =
      tag === 'svg' || (nameSpaceContext && useContext(nameSpaceContext) === 'svg')
        ? (key) => toSVGAttributeName(normalizeIntrinsicElementKey(key))
        : (key) => normalizeIntrinsicElementKey(key)
    for (let [key, v] of Object.entries(props)) {
      key = normalizeKey(key)
      if (!isValidAttributeName(key)) {
        continue
      }
      if (key === 'children') {
        // skip children
      } else if (
        key === 'dangerouslySetInnerHTML' &&
        typeof v === 'object' &&
        v !== null &&
        '__html' in v
      ) {
        if (children.length > 0) {
          throw new Error('Can only set one of `children` or `props.dangerouslySetInnerHTML`.')
        }

        children = [raw(v.__html)]
      } else {
        attributeToBuffer(buffer, ' ', key, v, tag)
      }
    }

    if (emptyTags.includes(tag as string) && children.length === 0) {
      buffer[0] += '/>'
      return
    }

    buffer[0] += '>'

    childrenToStringToBuffer(children, buffer)

    buffer[0] += `</${tag}>`
  }
}

constructor(tag: string | Function, props: Props, children: Child[]) {
  if (typeof tag !== 'function' && !isValidTagName(tag)) {
    throw new Error(`Invalid JSX tag name: ${tag}`)
  }
  this.tag = tag
  this.props = props
  this.children = children
}

get type(): string | Function {
  return this.tag as string
}

get ref(): any {
  return this.props.ref || null
}

toString(): string | Promise<string> {
  const render = () => {
    const buffer: StringBufferWithCallbacks = [''] as StringBufferWithCallbacks
    this.toStringToBuffer(buffer)
    return buffer.length === 1
      ? 'callbacks' in buffer
        ? resolveCallbackSync(raw(buffer[0], buffer.callbacks)).toString()
        : buffer[0]
      : stringBufferToString(buffer, buffer.callbacks).then(markRenderedJSX)
  }
  return runWithRenderContext(render)
}

toStringToBuffer(buffer: StringBufferWithCallbacks): void {
  const tag = this.tag as string
  const props = this.props
  let { children } = this

  buffer[0] += `<${tag}`

  const normalizeKey: (key: string) => string =
    tag === 'svg' || (nameSpaceContext && useContext(nameSpaceContext) === 'svg')
      ? (key) => toSVGAttributeName(normalizeIntrinsicElementKey(key))
      : (key) => normalizeIntrinsicElementKey(key)
  for (let [key, v] of Object.entries(props)) {
    key = normalizeKey(key)
    if (!isValidAttributeName(key)) {
      continue
    }
    if (key === 'children') {
      // skip children
    } else if (
      key === 'dangerouslySetInnerHTML' &&
      typeof v === 'object' &&
      v !== null &&
      '__html' in v
    ) {
      if (children.length > 0) {
        throw new Error('Can only set one of `children` or `props.dangerouslySetInnerHTML`.')
      }

      children = [raw(v.__html)]
    } else {
      attributeToBuffer(buffer, ' ', key, v, tag)
    }
  }

  if (emptyTags.includes(tag as string) && children.length === 0) {
    buffer[0] += '/>'
    return
  }

  buffer[0] += '>'

  childrenToStringToBuffer(children, buffer)

  buffer[0] += `</${tag}>`
}

class JSXFunctionNode extends JSXNode {
  override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
    const { children } = this

    const props = { ...this.props }
    if (children.length) {
      props.children = children.length === 1 ? children[0] : children
    }

    const res = (this.tag as Function).call(null, props)

    if (typeof res === 'boolean' || res == null) {
      // boolean or null or undefined
      return
    } else if (res instanceof Promise) {
      if (globalContexts.length === 0) {
        buffer.unshift('', resolveFunctionComponentResult(res))
      } else {
        // save the current context state for resuming the suspended subtree
        buffer.unshift('', resolveFunctionComponentResult(res, captureRenderContext()))
      }
    } else if (res instanceof JSXNode) {
      res.toStringToBuffer(buffer)
    } else if (Array.isArray(res)) {
      childrenToStringToBuffer(res, buffer)
    } else if (typeof res === 'number' || (res as HtmlEscaped).isEscaped) {
      buffer[0] += res
      if (res.callbacks) {
        buffer.callbacks ||= []
        buffer.callbacks.push(...res.callbacks)
      }
    } else {
      escapeToBuffer(res, buffer)
    }
  }
}

override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
  const { children } = this

  const props = { ...this.props }
  if (children.length) {
    props.children = children.length === 1 ? children[0] : children
  }

  const res = (this.tag as Function).call(null, props)

  if (typeof res === 'boolean' || res == null) {
    // boolean or null or undefined
    return
  } else if (res instanceof Promise) {
    if (globalContexts.length === 0) {
      buffer.unshift('', resolveFunctionComponentResult(res))
    } else {
      // save the current context state for resuming the suspended subtree
      buffer.unshift('', resolveFunctionComponentResult(res, captureRenderContext()))
    }
  } else if (res instanceof JSXNode) {
    res.toStringToBuffer(buffer)
  } else if (Array.isArray(res)) {
    childrenToStringToBuffer(res, buffer)
  } else if (typeof res === 'number' || (res as HtmlEscaped).isEscaped) {
    buffer[0] += res
    if (res.callbacks) {
      buffer.callbacks ||= []
      buffer.callbacks.push(...res.callbacks)
    }
  } else {
    escapeToBuffer(res, buffer)
  }
}

export class JSXFragmentNode extends JSXNode {
  override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
    childrenToStringToBuffer(this.children, buffer)
  }
}

override toStringToBuffer(buffer: StringBufferWithCallbacks): void {
  childrenToStringToBuffer(this.children, buffer)
}

export const jsx = (tag: string | Function, props: Props | null, ...children: Child[]): JSXNode => {
  props ??= {}
  if (children.length) {
    props.children = children.length === 1 ? children[0] : children
  }

  const key = props.key
  delete props['key']

  const node = jsxFn(tag, props, children)
  node.key = key
  return node
}

export const jsxFn = (tag: string | Function, props: Props, children: Child[]): JSXNode => {
  if (!initDomRenderer) {
    for (const k in domRenderers) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      ;(intrinsicElementTags[k as keyof typeof intrinsicElementTags] as any)[DOM_RENDERER] =
        domRenderers[k]
    }
    initDomRenderer = true
  }

  if (typeof tag === 'function') {
    return new JSXFunctionNode(tag, props, children)
  } else if (intrinsicElementTags[tag as keyof typeof intrinsicElementTags]) {
    return new JSXFunctionNode(
      intrinsicElementTags[tag as keyof typeof intrinsicElementTags],
      props,
      children
    )
  } else if (tag === 'svg' || tag === 'head') {
    nameSpaceContext ||= createContext('')
    return new JSXNode(tag, props, [
      new JSXFunctionNode(
        nameSpaceContext,
        {
          value: tag,
        },
        children
      ),
    ])
  } else {
    return new JSXNode(tag, props, children)
  }
}

export const shallowEqual = (a: Props, b: Props): boolean => {
  if (a === b) {
    return true
  }

  const aKeys = Object.keys(a).sort()
  const bKeys = Object.keys(b).sort()
  if (aKeys.length !== bKeys.length) {
    return false
  }

  for (let i = 0, len = aKeys.length; i < len; i++) {
    if (
      aKeys[i] === 'children' &&
      bKeys[i] === 'children' &&
      !a.children?.length &&
      !b.children?.length
    ) {
      continue
    } else if (a[aKeys[i]] !== b[aKeys[i]]) {
      return false
    }
  }

  return true
}

export const isValidElement = (element: unknown): element is JSXNode => {
  return !!(element && typeof element === 'object' && 'tag' in element && 'props' in element)
}

